import 'package:flutter/material.dart';import '../services/firebase_service.dart';import '../models/product.dart';
class ProductsScreen extends StatelessWidget{const ProductsScreen({super.key});@override Widget build(BuildContext c)=>StreamBuilder<List<Product>>(stream:FirebaseService().products(),builder:(c,s){if(s.hasError)return Center(child:Text('Error: ${s.error}'));if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.isEmpty)return const Center(child:Text('No products yet. Add your first product.'));return ListView.builder(padding:const EdgeInsets.all(16),itemCount:s.data!.length,itemBuilder:(_,i){final p=s.data![i];return Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.image_outlined)),title:Text(p.name),subtitle:Text(p.category),trailing:Text('₹${p.price.toStringAsFixed(0)}')));});});}
